from AlgorithmImports import *
from collections import deque
import math


class ExactStrategySystem(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily, fillForward=False).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily, fillForward=False).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily, fillForward=False).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily, fillForward=False).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily, fillForward=False).Symbol

        self.required_symbols = [
            self.spy,
            self.aapl,
            self.ibm,
            self.bac,
            self.aig
        ]

        self.SetWarmUp(101, Resolution.Daily)

        self.spy_closes = deque(maxlen=101)
        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.rsi_period = 14
        self.aapl_rsi_changes = 0
        self.aapl_gain_sum = 0.0
        self.aapl_loss_sum = 0.0
        self.aapl_average_gain = None
        self.aapl_average_loss = None
        self.aapl_rsi_value = None

        self.lot_shares = {
            "A": 0,
            "B": 0
        }

        self.pending_orders = {
            "A": 0,
            "B": 0
        }

        self.order_slots = {}

    def OnData(self, data):
        bars = {}
        all_bars_present = True

        for symbol in self.required_symbols:
            if not data.Bars.ContainsKey(symbol):
                all_bars_present = False
                continue

            bar = data.Bars[symbol]
            if bar is None or getattr(bar, "IsFillForward", False):
                all_bars_present = False
                continue

            bars[symbol] = bar

        spy_cross_above = False
        spy_cross_below = False

        if self.spy in bars:
            spy_cross_above, spy_cross_below = self._update_spy(
                float(bars[self.spy].Close)
            )

        if self.aapl in bars:
            self._update_aapl(float(bars[self.aapl].Close))

        if self.IsWarmingUp or not all_bars_present:
            return

        if (
            self.lot_shares["A"] == 0
            and self.pending_orders["A"] == 0
            and spy_cross_above
        ):
            close = float(bars[self.spy].Close)
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            quantity = int(math.floor(target_value / close))

            if quantity > 0:
                self._submit_order(
                    self.spy,
                    quantity,
                    "A",
                    "Strategy A entry"
                )

        elif (
            self.lot_shares["A"] > 0
            and self.pending_orders["A"] == 0
            and spy_cross_below
        ):
            self._submit_order(
                self.spy,
                -self.lot_shares["A"],
                "A",
                "Strategy A exit"
            )

        if (
            self.lot_shares["B"] > 0
            and self.pending_orders["B"] == 0
            and self.aapl_rsi_value is not None
            and self.aapl_rsi_value > 60.0
        ):
            self._submit_order(
                self.aapl,
                -self.lot_shares["B"],
                "B",
                "Strategy B exit"
            )

        elif (
            self.lot_shares["B"] == 0
            and self.pending_orders["B"] == 0
            and self.aapl_red_streak >= 3
            and float(self.Portfolio.Cash) >= 20000.0
        ):
            close = float(bars[self.aapl].Close)
            quantity = int(math.floor(20000.0 / close))

            if quantity > 0:
                self._submit_order(
                    self.aapl,
                    quantity,
                    "B",
                    "Strategy B entry"
                )

    def _simple_moving_average(self, values, period):
        if len(values) < period:
            return None

        return sum(list(values)[-period:]) / float(period)

    def _update_spy(self, close):
        previous_close = self.spy_previous_close
        previous_sma = self.spy_previous_sma

        self.spy_closes.append(close)
        current_sma = self._simple_moving_average(self.spy_closes, 100)

        crosses_above = (
            previous_close is not None
            and previous_sma is not None
            and current_sma is not None
            and previous_close <= previous_sma
            and close > current_sma
        )

        crosses_below = (
            previous_close is not None
            and previous_sma is not None
            and current_sma is not None
            and previous_close >= previous_sma
            and close < current_sma
        )

        self.spy_previous_close = close
        self.spy_previous_sma = current_sma

        return crosses_above, crosses_below

    def _update_aapl(self, close):
        previous_close = self.aapl_previous_close

        if previous_close is None:
            self.aapl_red_streak = 0
        elif close < previous_close:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        if previous_close is not None:
            change = close - previous_close
            gain = max(change, 0.0)
            loss = max(-change, 0.0)

            if self.aapl_rsi_changes < self.rsi_period:
                self.aapl_gain_sum += gain
                self.aapl_loss_sum += loss
                self.aapl_rsi_changes += 1

                if self.aapl_rsi_changes == self.rsi_period:
                    self.aapl_average_gain = (
                        self.aapl_gain_sum / self.rsi_period
                    )
                    self.aapl_average_loss = (
                        self.aapl_loss_sum / self.rsi_period
                    )
            else:
                self.aapl_average_gain = (
                    (self.aapl_average_gain * (self.rsi_period - 1)) + gain
                ) / self.rsi_period

                self.aapl_average_loss = (
                    (self.aapl_average_loss * (self.rsi_period - 1)) + loss
                ) / self.rsi_period

            if self.aapl_rsi_changes >= self.rsi_period:
                if self.aapl_average_loss == 0.0:
                    if self.aapl_average_gain > 0.0:
                        self.aapl_rsi_value = 100.0
                    else:
                        self.aapl_rsi_value = 0.0
                else:
                    relative_strength = (
                        self.aapl_average_gain / self.aapl_average_loss
                    )
                    self.aapl_rsi_value = (
                        100.0 - (100.0 / (1.0 + relative_strength))
                    )

        self.aapl_previous_close = close

    def _submit_order(self, symbol, quantity, slot, tag):
        self.pending_orders[slot] += 1

        ticket = self.MarketOrder(
            symbol,
            quantity,
            tag=tag
        )

        if ticket is None:
            self.pending_orders[slot] = max(
                0,
                self.pending_orders[slot] - 1
            )
            return

        self.order_slots[ticket.OrderId] = slot

    def OnOrderEvent(self, order_event):
        slot = self.order_slots.get(order_event.OrderId)

        if slot is None:
            event_ticket = getattr(order_event, "Ticket", None)
            event_tag = ""

            if event_ticket is not None:
                event_tag = str(getattr(event_ticket, "Tag", "") or "")

            if event_tag.startswith("Strategy A"):
                slot = "A"
            elif event_tag.startswith("Strategy B"):
                slot = "B"

        if slot is None:
            return

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.PartiallyFilled
        ):
            self.lot_shares[slot] += int(order_event.FillQuantity)
            self.lot_shares[slot] = max(0, self.lot_shares[slot])

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.pending_orders[slot] = max(
                0,
                self.pending_orders[slot] - 1
            )
