from AlgorithmImports import *


class ExactStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily, fillForward=False).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily, fillForward=False).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily, fillForward=False).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily, fillForward=False).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily, fillForward=False).Symbol

        self.required_symbols = [
            self.spy,
            self.aapl,
            self.ibm,
            self.bac,
            self.aig
        ]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data):
        bars = data.Bars

        spy_close = (
            float(bars[self.spy].Close)
            if bars.ContainsKey(self.spy)
            else None
        )
        aapl_close = (
            float(bars[self.aapl].Close)
            if bars.ContainsKey(self.aapl)
            else None
        )

        previous_spy_close = self.previous_spy_close
        previous_spy_sma = self.previous_spy_sma
        previous_aapl_close = self.previous_aapl_close

        current_spy_sma = (
            float(self.spy_sma.Current.Value)
            if spy_close is not None and self.spy_sma.IsReady
            else None
        )

        if aapl_close is not None:
            if previous_aapl_close is None:
                current_red_streak = 0
            elif aapl_close < previous_aapl_close:
                current_red_streak = self.aapl_red_streak + 1
            else:
                current_red_streak = 0
        else:
            current_red_streak = self.aapl_red_streak

        all_bars_present = all(
            bars.ContainsKey(symbol)
            for symbol in self.required_symbols
        )

        if not self.IsWarmingUp and all_bars_present:
            spy_crosses_above = (
                previous_spy_close is not None
                and previous_spy_sma is not None
                and current_spy_sma is not None
                and previous_spy_close <= previous_spy_sma
                and spy_close > current_spy_sma
            )

            spy_crosses_below = (
                previous_spy_close is not None
                and previous_spy_sma is not None
                and current_spy_sma is not None
                and previous_spy_close >= previous_spy_sma
                and spy_close < current_spy_sma
            )

            if self.Portfolio[self.spy].Quantity > 0:
                if spy_crosses_below and not self.Transactions.GetOpenOrders(self.spy):
                    self.MarketOrder(
                        self.spy,
                        -self.Portfolio[self.spy].Quantity
                    )
            elif spy_crosses_above and not self.Transactions.GetOpenOrders(self.spy):
                quantity = int(
                    (0.40 * float(self.Portfolio.TotalPortfolioValue))
                    / spy_close
                )
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)

            aapl_sell = (
                self.aapl_rsi.IsReady
                and float(self.aapl_rsi.Current.Value) > 60
            )

            if self.Portfolio[self.aapl].Quantity > 0:
                if aapl_sell and not self.Transactions.GetOpenOrders(self.aapl):
                    self.MarketOrder(
                        self.aapl,
                        -self.Portfolio[self.aapl].Quantity
                    )
            elif (
                current_red_streak >= 3
                and float(self.Portfolio.Cash) >= 20000.0
                and not self.Transactions.GetOpenOrders(self.aapl)
            ):
                quantity = int(20000.0 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)

        if spy_close is not None:
            self.previous_spy_close = spy_close

        if current_spy_sma is not None:
            self.previous_spy_sma = current_spy_sma

        if aapl_close is not None:
            self.previous_aapl_close = aapl_close
            self.aapl_red_streak = current_red_streak
